import React, { useState } from "react";
import { Container, TextField, Button, Typography, Box, Paper, MenuItem, IconButton, InputAdornment, AppBar, Toolbar } from "@mui/material";
import { Visibility, VisibilityOff } from "@mui/icons-material";
import { useNavigate } from "react-router-dom";

const schools = ["Engineering", "Business", "Arts"];
const courses = {
  Engineering: ["ENG101", "ENG102", "ENG103"],
  Business: ["BUS201", "BUS202", "BUS203"],
  Arts: ["ART301", "ART302", "ART303"],
};

const Register = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    firstName: "",
    lastName: "",
    studentId: "",
    school: "",
    course: "",
    password: "",
    confirmPassword: "",
    showPassword: false,
  });

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleTogglePassword = () => {
    if (formData.password) {
      setFormData({ ...formData, showPassword: !formData.showPassword });
    }
  };

  const validatePassword = (password) => {
    return /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]{8,}$/.test(password);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!validatePassword(formData.password)) {
      alert("Password must be at least 8 characters long, include a number, uppercase letter, and special character.");
      return;
    }
    if (formData.password !== formData.confirmPassword) {
      alert("Passwords do not match.");
      return;
    }
    if (formData.studentId.length !== 8 || !/^[a-zA-Z0-9]+$/.test(formData.studentId)) {
      alert("Student ID must be exactly 8 alphanumeric characters.");
      return;
    }
    console.log("Form Submitted", formData);
    navigate("/dashboard");
  };

  return (
    <Box sx={{ minHeight: "100vh", background: "rgba(100, 200, 225, 0.6)", backdropFilter: "blur(15px)", display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
      <AppBar position="fixed" color="primary">
        <Toolbar>
          <Typography variant="h6">SRC E-Voting System</Typography>
        </Toolbar>
      </AppBar>
      <Container maxWidth="sm" sx={{ mt: 12 }}>
        <Paper elevation={3} sx={{ p: 4 }}>
          <Typography variant="h5" fontWeight="bold" gutterBottom>
            Registration
          </Typography>
          <Box component="form" onSubmit={handleSubmit} sx={{ display: "flex", flexDirection: "column", gap: 2 }}>
            <Box sx={{ display: "flex", gap: 2 }}>
              <TextField label="First Name" name="firstName" value={formData.firstName} onChange={handleChange} required fullWidth sx={{ '&:hover, &:focus-within': { borderColor: '#1565c0', boxShadow: '0 0 5px #1565c0' } }} />
              <TextField label="Last Name" name="lastName" value={formData.lastName} onChange={handleChange} required fullWidth sx={{ '&:hover, &:focus-within': { borderColor: '#1565c0', boxShadow: '0 0 5px #1565c0' } }} />
            </Box>
            <TextField label="Student ID" name="studentId" value={formData.studentId} onChange={handleChange} required fullWidth sx={{ '&:hover, &:focus-within': { borderColor: '#1565c0', boxShadow: '0 0 5px #1565c0' } }} />
            <Box sx={{ display: "flex", gap: 2, mt: 3 }}>
              <TextField 
                select 
                label="School" 
                name="school" 
                value={formData.school} 
                onChange={handleChange} 
                required 
                fullWidth
                sx={{ '&:hover, &:focus-within': { borderColor: '#1565c0', boxShadow: '0 0 5px #1565c0' } }}
              >
                {schools.map((school) => (
                  <MenuItem key={school} value={school}>{school}</MenuItem>
                ))}
              </TextField>
              <TextField 
                select 
                label="Course Code" 
                name="course" 
                value={formData.course} 
                onChange={handleChange} 
                required 
                fullWidth
                disabled={!formData.school}
                sx={{ '&:hover, &:focus-within': { borderColor: '#1565c0', boxShadow: '0 0 5px #1565c0' } }}
              >
                {formData.school && courses[formData.school].map((course) => (
                  <MenuItem key={course} value={course}>{course}</MenuItem>
                ))}
              </TextField>
            </Box>
            <Box sx={{ mt: 5 }}></Box>
            <TextField 
              label="Password" 
              name="password" 
              type={formData.showPassword ? "text" : "password"} 
              value={formData.password} 
              onChange={handleChange} 
              required 
              fullWidth
              sx={{ '&:hover, &:focus-within': { borderColor: '#1565c0', boxShadow: '0 0 5px #1565c0' } }}
              InputProps={{
                endAdornment: (
                  <InputAdornment position="end">
                    {formData.password && (
                      <IconButton onClick={handleTogglePassword} edge="end">
                        {formData.showPassword ? <VisibilityOff /> : <Visibility />}
                      </IconButton>
                    )}
                  </InputAdornment>
                ),
              }}
            />
            <TextField label="Confirm Password" name="confirmPassword" type="password" value={formData.confirmPassword} onChange={handleChange} required fullWidth sx={{ '&:hover, &:focus-within': { borderColor: '#1565c0', boxShadow: '0 0 5px #1565c0' } }} />
            <Button type="submit" variant="contained" color="success" fullWidth sx={{ width: "110%" }}>
              Register
            </Button>
            <Typography variant="body2" sx={{ mt: 2, textAlign: "center" }}>
              Already have an account? <Button color="primary" onClick={() => navigate("/login")} sx={{ textTransform: "none" }}>Login</Button>
            </Typography>
          </Box>
        </Paper>
      </Container>
    </Box>
  );
};

export default Register;
